<?php
namespace App\Http\Controllers;
use App\Models\Language; use Illuminate\Http\Request;
class AdminLanguageController extends Controller { private function admin(){abort_unless(auth()->check()&&auth()->user()->role==='admin',403);} public function index(){ $this->admin();$languages=Language::orderByDesc('is_default')->orderBy('name')->get();return view('admin.languages.index',compact('languages'));} public function create(){ $this->admin();return view('admin.languages.form',['language'=>null]);} public function store(Request $r){$this->admin();$d=$r->validate(['code'=>'required|alpha_dash|max:10|unique:languages,code','name'=>'required|string|max:80','native_name'=>'required|string|max:80','direction'=>'required|in:ltr,rtl']);$language=Language::create($d+['is_active'=>$r->boolean('is_active'),'is_default'=>false]);return redirect()->route('admin.languages.index')->with('success','تمت إضافة اللغة.');} public function edit(Language $language){$this->admin();return view('admin.languages.form',compact('language'));} public function update(Request $r,Language $language){$this->admin();$d=$r->validate(['code'=>'required|alpha_dash|max:10|unique:languages,code,'.$language->id,'name'=>'required|string|max:80','native_name'=>'required|string|max:80','direction'=>'required|in:ltr,rtl']);$language->update($d+['is_active'=>$r->boolean('is_active')]);return redirect()->route('admin.languages.index')->with('success','تم تحديث اللغة.');} public function destroy(Language $language){$this->admin();abort_if($language->is_default,422,'لا يمكن حذف اللغة الافتراضية.');$language->delete();return back()->with('success','تم حذف اللغة.');} public function setDefault(Language $language){$this->admin();Language::query()->update(['is_default'=>false]);$language->update(['is_default'=>true,'is_active'=>true]);\App\Models\Setting::updateOrCreate(['key'=>'default_language'],['value'=>$language->code,'type'=>'string']);return back()->with('success','تم تغيير اللغة الافتراضية.');} }
